#!/usr/bin/env bash

###############################################################################
#
# Authentik-netcup Project
#
# File:
#   scripts/lib/env/helpers.sh
#
# Description:
#   Helper functions for environment files.
#
###############################################################################

###############################################################################
# Is comment
###############################################################################

env_is_comment()
{
    [[ "$1" =~ ^[[:space:]]*# ]]
}

###############################################################################
# Is blank line
###############################################################################

env_is_blank()
{
    [[ -z "$1" ]]
}

###############################################################################
# Is variable
###############################################################################

env_is_variable()
{
    [[ "$1" == *=* ]]
}

###############################################################################
# Variable name
###############################################################################

env_variable_name()
{
    printf '%s\n' "${1%%=*}"
}

###############################################################################
# Variable value
###############################################################################

env_variable_value()
{
    printf '%s\n' "${1#*=}"
}

###############################################################################
# Placeholder
#
# .env.example marks unset production values with the set_ prefix.
# Those values are not usable in a deployment.
###############################################################################

env_is_placeholder()
{
    [[ "$1" == set_* ]]
}

###############################################################################
# Sensitive variable
#
# Difference reports must not print these values.
###############################################################################

env_is_sensitive()
{
    local key="$1"

    [[ "${key}" == *PASSWORD* || "${key}" == *SECRET* || "${key}" == PG_PASS ]]
}